     else{var candidate=FacialEdits.Resize(groupOriginals[c.Id],edge,delta);var previous=FacialEdits.Copy(c);FacialEdits.Timing(c,candidate);try{FacialTimeline.Validate(project.FacialTracks);validDrag=true;}catch(System.IO.InvalidDataException){validDrag=false;FacialEdits.Timing(c,previous);}}
     Canvas.SetLeft(block,axis.X(c.Start,width));block.Width=Math.Max(8,(c.End-c.Start)*scale);ClipBlock();Select(c);};
    block.MouseLeftButtonUp+=(_,e)=>{if(!dragging)return;dragging=false;block.ReleaseMouseCapture();if(!validDrag){foreach(var old in groupOriginals.Values)FacialEdits.Timing(project.FacialTracks.Single(t=>t.Id==old.Id),old);curveHistory.Cancel();Draw();Select(c);e.Handled=true;return;}try{FacialTimeline.Validate(project.FacialTracks);curveHistory.Commit(project.FacialTracks);changed();}catch(Exception ex){curveHistory.Cancel();foreach(var old in groupOriginals.Values)FacialEdits.Timing(project.FacialTracks.Single(t=>t.Id==old.Id),old);MessageBox.Show(UiText.Error(ex.Message));}Draw();Select(c);e.Handled=true;};
    block.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape&&dragging){block.ReleaseMouseCapture();e.Handled=true;}};
    block.LostMouseCapture+=(_,_)=>{if(dragging){dragging=false;curveHistory.Cancel();foreach(var old in groupOriginals.Values)FacialEdits.Timing(project.FacialTracks.Single(t=>t.Id==old.Id),old);Select(c);Draw();}};
   }
   var head=new Line{X1=axis.X(cursor(),width),X2=axis.X(cursor(),width),Y1=20,Y2=60,Stroke=StudioTheme.Accent,StrokeThickness=2,IsHitTestVisible=false};canvas.Children.Add(head);playheads.Add((head,scale));
  }
  shownCursor=double.NaN;RenderCursor(null,EventArgs.Empty);
 }
